import { describeError } from "../engine/utils/redaction.js";
export function failedDiagnostic(code, error) {
    return {
        code,
        severity: "error",
        message: describeError(error),
    };
}
export function diagnosticReport(command, status, diagnostics) {
    return {
        format: "sync-engine.diagnostic-report",
        version: 1,
        command,
        status,
        diagnostics,
    };
}
/** Render exactly one newline-terminated JSON document for stdout. */
export function renderJsonDocument(document) {
    return `${JSON.stringify(document)}\n`;
}
export function writeJsonDocument(document) {
    process.stdout.write(renderJsonDocument(document));
}
